// Returns the maximum element of a non-empty integer vector.
fn max_array(a: Vec<i32>) -> i32 {
    // Precondition: a.len() >= 1
    let mut m = a[0];
    for &x in a.iter().skip(1) {
        if x > m {
            m = x;
        }
    }
    m
}

